const getColorValue = (colorName) => {
  if (!colorName) return null;
  const name = colorName.trim().toLowerCase();
  
  const colorMap = {
    'red': '#ef4444',
    'blue': '#3b82f6',
    'light blue': '#bae6fd',
    'green': '#10b981',
    'yellow': '#f59e0b',
    'black': '#000000',
    'white': '#ffffff',
    'pink': '#ec4899',
    'purple': '#8b5cf6',
    'gray': '#6b7280',
    'grey': '#6b7280',
    'orange': '#f97316',
    'brown': '#78350f',
    'cream': '#fdf6e2',
    'navy': '#1e3a8a',
    'gold': '#d97706',
    'silver': '#d1d5db',
    'maroon': '#800000',
    'olive': '#808000',
    'teal': '#008080',
    'magenta': '#ff00ff',
    'lavender': '#e6e6fa',
    'beige': '#f5f5dc',
    'mustard': '#e1ad01',
    'peach': '#ffcba4',
    'mint': '#98ff98',
    'charcoal': '#36454f'
  };
  
  if (name.startsWith('#') || name.startsWith('rgb') || name.startsWith('hsl')) {
    return name;
  }
  
  return colorMap[name] || name;
};

