  const handleSaveStock = async (e) => {
    e.preventDefault();
    if (!editingStockCombination) return;
    
    const amount = parseInt(stockUpdateAmount);
    if (isNaN(amount)) {
      triggerToast('Please enter a valid stock amount', 'error');
      return;
    }
    
    try {
      setActionLoading(true);
      const authToken = token || localStorage.getItem('vaugun_token');
      const res = await fetch(`${API_BASE_URL}/products/stock`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${authToken}`
        },
        body: JSON.stringify({
          action: 'update',
          productId: editingStockCombination.productId,
          variant: editingStockCombination.variant,
          color: editingStockCombination.color,
          stock: amount,
          mode: stockUpdateMode
        })
      });
      
      const resData = await res.json();
      if (res.ok && resData.success) {
        triggerToast('Stock updated successfully!', 'success');
        
        let newStock = amount;
        if (stockUpdateMode === 'add') {
          newStock = editingStockCombination.currentStock + amount;
        }
        if (newStock < 0) newStock = 0;

        if (typeof window !== 'undefined') {
          const updateInfo = {
            productId: editingStockCombination.productId,
            variant: editingStockCombination.variant || '',
            color: editingStockCombination.color || '',
            stock: newStock,
            timestamp: Date.now()
          };
          localStorage.setItem('daivika_last_stock_update', JSON.stringify(updateInfo));
          window.dispatchEvent(new CustomEvent('daivika_stock_update', {
            detail: updateInfo
          }));
        }
        
        setProducts(prev => prev.map(p => {
          if (p._id === editingStockCombination.productId) {
            const newInv = (p.inventory || []).map(inv => {
              if ((inv.variant || '') === (editingStockCombination.variant || '') && (inv.color || '') === (editingStockCombination.color || '')) {
                return { ...inv, stock: newStock };
              }
              return inv;
            });
            
            const exists = (p.inventory || []).some(inv => 
              (inv.variant || '') === (editingStockCombination.variant || '') && 
              (inv.color || '') === (editingStockCombination.color || '')
            );
            if (!exists) {
              newInv.push({
                variant: editingStockCombination.variant || '',
                color: editingStockCombination.color || '',
                stock: newStock
              });
            }
            
            return { ...p, inventory: newInv };
          }
          return p;
        }));
        
        setEditingStockCombination(null);
        setStockUpdateAmount('');
      } else {
        triggerToast(resData.message || 'Failed to update stock', 'error');
      }
    } catch (err) {
      console.error(err);
      triggerToast('Server error while saving stock', 'error');
    } finally {
      setActionLoading(false);
    }
  };

