  // Helper to normalize specifications from arrays of strings, objects, or key-value pairs
  const normalizeSpecs = (rawSpecs) => {
    if (!rawSpecs) return [];
    let parsed = rawSpecs;
    if (typeof parsed === 'string') {
      try {
        parsed = JSON.parse(parsed);
      } catch (e) {
        return [];
      }
    }
    if (!Array.isArray(parsed)) return [];

    // Check if it is an alternating array of strings: ['Key1', 'Val1', 'Key2', 'Val2']
    if (parsed.length > 0 && parsed.every(item => typeof item === 'string') && !parsed.some(item => typeof item === 'string' && item.includes(':')) && parsed.length % 2 === 0) {
      const pairs = [];
      for (let i = 0; i < parsed.length; i += 2) {
        pairs.push({ key: String(parsed[i] || ''), value: String(parsed[i + 1] || '') });
      }
      return pairs;
    }

    return parsed.map(item => {
      if (typeof item === 'string') {
        if (item.includes(':')) {
          const parts = item.split(':');
          return { key: parts[0].trim(), value: parts.slice(1).join(':').trim() };
        }
        return { key: item.trim(), value: '' };
      }
      if (item && typeof item === 'object') {
        return {
          key: String(item.key || item.name || item.label || item.title || ''),
          value: String(item.value || item.val || item.desc || item.description || '')
        };
      }
      return null;
    }).filter(Boolean);
  };

  // Helper to normalize highlights from strings, objects, or arrays
  const getAdminProductImage = (p) => {
    if (!p) return 'https://images.unsplash.com/photo-1541099649105-f69ad21f3246?w=200&auto=format&fit=crop&q=80';
    let img = p.image || (Array.isArray(p.images) && p.images[0]) || (p.variants?.[0]?.images?.[0]) || (p.colors?.[0]?.images?.[0]) || (p.textures?.[0]?.image) || '';
    if (img && typeof img === 'object') {
      img = img.url || img.src || img.path || '';
    }
    if (!img || typeof img !== 'string') {
      const cat = String(p.category || '').toLowerCase();
      if (cat.includes('jewel') || cat.includes('ring') || cat.includes('chain')) {
        return 'https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?w=200&auto=format&fit=crop&q=80';
      }
      return 'https://images.unsplash.com/photo-1541099649105-f69ad21f3246?w=200&auto=format&fit=crop&q=80';
    }
    let cleanImg = img.trim();
    if (cleanImg.includes('localhost:') && cleanImg.includes('/uploads/')) {
      const idx = cleanImg.indexOf('/uploads/');
      cleanImg = cleanImg.slice(idx);
    }
    if (cleanImg.startsWith('http://') || cleanImg.startsWith('https://') || cleanImg.startsWith('data:')) {
      return cleanImg;
    }
    if (cleanImg.startsWith('/')) {
      return cleanImg;
    }
    return `/${cleanImg}`;
  };

