  // Real Orders State — loaded purely from localStorage (only confirmed/paid orders)
  const [orders, setOrders] = useState(() => {
    if (typeof window === 'undefined') return [];
    const saved = localStorage.getItem('vaugun_orders');
    if (!saved) return [];
    try {
      const parsed = JSON.parse(saved);
      return Array.isArray(parsed) ? parsed.filter(o => {
        const oid = (o?._id || o?.id || '').toString();
        if (!oid || ['ord_1', 'ord_2', 'ord_3'].includes(oid)) return false;
        if (o.status === 'Pending Payment') return false;
        return true;
      }) : [];
    } catch {
      return [];
    }
  });






  // Real-time sync: reload orders when Checkout places a new order in another tab/same tab
  useEffect(() => {
    const handleStorageChange = (e) => {
      if (e.key === 'vaugun_orders' && e.newValue) {
        try {
          const incoming = JSON.parse(e.newValue);
          if (Array.isArray(incoming)) {
            const cleanIncoming = incoming.filter(o => {
              const oid = (o?._id || o?.id || '').toString();
              if (!oid || ['ord_1', 'ord_2', 'ord_3'].includes(oid)) return false;
              if (o.status === 'Pending Payment') return false;
              return true;
            });
            setOrders(prev => {
              const merged = [...cleanIncoming];
              prev.forEach(existing => {
                if (!merged.some(o => o._id === existing._id)) {
                  merged.push(existing);
                }
              });
              return merged;
            });
          }
        } catch (err) {
          console.error('Error syncing orders from storage:', err);
        }
      }
    };
    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

