  const [cardImageUploading, setCardImageUploading] = useState({});

  const handleFeatureCardImageUpload = async (idx, file) => {
    if (!file) return;
    setCardImageUploading(prev => ({ ...prev, [idx]: true }));
    const formData = new FormData();
    formData.append('image', await shrinkImage(file));
    try {
      const authToken = token || localStorage.getItem('vaugun_token');
      const res = await fetch(`${API_BASE_URL}/admin/upload-image`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${authToken}`
        },
        body: formData
      });
      const resData = await res.json();
      if (res.ok && resData.success && resData.imageUrl) {
        setFeatureCards(prev => prev.map((c, i) => i === idx ? { ...c, image: resData.imageUrl } : c));
        triggerToast(`Card #${idx + 1} image uploaded!`, 'success');
      } else {
        const reader = new FileReader();
        reader.onload = (e) => {
          setFeatureCards(prev => prev.map((c, i) => i === idx ? { ...c, image: e.target.result } : c));
          triggerToast(`Card #${idx + 1} image set!`, 'success');
        };
        reader.readAsDataURL(file);
      }
    } catch (err) {
      console.error(err);
      const reader = new FileReader();
      reader.onload = (e) => {
        setFeatureCards(prev => prev.map((c, i) => i === idx ? { ...c, image: e.target.result } : c));
        triggerToast(`Card #${idx + 1} image set!`, 'success');
      };
      reader.readAsDataURL(file);
    } finally {
      setCardImageUploading(prev => ({ ...prev, [idx]: false }));
    }
  };

