  const [isUploadingBannerDesktop, setIsUploadingBannerDesktop] = useState({});
  const [isUploadingBannerMobile, setIsUploadingBannerMobile] = useState({});

  const handleBannerImageUpload = async (sIdx, type, file) => {
    if (!file) return;

    // 1. Instant local preview
    const reader = new FileReader();
    reader.onload = (re) => {
      const dataUrl = re.target.result;
      setBanners(prev => {
        const updated = [...prev];
        if (type === 'desktop') {
          updated[sIdx] = { 
            ...updated[sIdx], 
            image: dataUrl,
            mobileImage: updated[sIdx]?.mobileImage || dataUrl
          };
        } else {
          updated[sIdx] = { 
            ...updated[sIdx], 
            mobileImage: dataUrl,
            image: updated[sIdx]?.image || dataUrl
          };
        }
        return updated;
      });
    };
    reader.readAsDataURL(file);

    // 2. Upload to server
    if (type === 'desktop') {
      setIsUploadingBannerDesktop(prev => ({ ...prev, [sIdx]: true }));
    } else {
      setIsUploadingBannerMobile(prev => ({ ...prev, [sIdx]: true }));
    }

    try {
      const formData = new FormData();
      formData.append('image', await shrinkImage(file));
      const authToken = token || 
        (typeof window !== 'undefined' ? (
          localStorage.getItem('vaugun_token') || 
          localStorage.getItem('daivika_token') || 
          localStorage.getItem('mykidzo_token') || 
          localStorage.getItem('token')
        ) : '');
      const res = await fetch(`${API_BASE_URL}/admin/upload-image`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${authToken}` },
        body: formData
      });
      const resData = await res.json();
      const imgUrl = resData.imageUrl || resData.data?.imageUrl;
      if (res.ok && imgUrl) {
        setBanners(prev => {
          const updated = [...prev];
          if (type === 'desktop') {
            updated[sIdx] = { 
              ...updated[sIdx], 
              image: imgUrl,
              mobileImage: (updated[sIdx]?.mobileImage && !updated[sIdx].mobileImage.startsWith('data:')) ? updated[sIdx].mobileImage : imgUrl
            };
          } else {
            updated[sIdx] = { 
              ...updated[sIdx], 
              mobileImage: imgUrl,
              image: (updated[sIdx]?.image && !updated[sIdx].image.startsWith('data:')) ? updated[sIdx].image : imgUrl
            };
          }
          return updated;
        });
        triggerToast(`Banner #${sIdx + 1} ${type === 'desktop' ? 'Desktop' : 'Mobile'} image uploaded! ✨`, 'success');
      } else {
        triggerToast(resData.message || 'Image loaded locally. Remember to click Save Banners.', 'info');
      }
    } catch (err) {
      console.error('Banner upload error:', err);
      triggerToast('Loaded preview locally. Click Save Banners to apply.', 'info');
    } finally {
      if (type === 'desktop') {
        setIsUploadingBannerDesktop(prev => ({ ...prev, [sIdx]: false }));
      } else {
        setIsUploadingBannerMobile(prev => ({ ...prev, [sIdx]: false }));
      }
    }
  };

