  const handleLogoUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const formData = new FormData();
    formData.append('image', await shrinkImage(file));

    try {
      setIsUploadingLogo(true);
      const authToken = token || localStorage.getItem('vaugun_token');
      const response = await fetch(`${API_BASE_URL}/admin/upload-logo`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${authToken}`
        },
        body: formData
      });
      const data = await response.json();
      if (data.success) {
        setInvoiceSettings(prev => ({ ...prev, companyLogo: data.imageUrl }));
        triggerToast('Logo uploaded successfully', 'success');
      } else {
        triggerToast(data.message || 'Failed to upload logo', 'error');
      }
    } catch (error) {
      console.error('Logo upload error:', error);
      triggerToast('Server error during upload', 'error');
    } finally {
      setIsUploadingLogo(false);
    }
  };

