  // Subscribe current admin device to push notifications for testing
  const subscribeAdminPush = async () => {
    if (typeof window === 'undefined' || !('serviceWorker' in navigator) || !('PushManager' in window)) {
      triggerToast('Push notifications are not supported in this browser.', 'error');
      return;
    }

    try {
      const registration = await navigator.serviceWorker.register('/sw.js');
      const permission = await Notification.requestPermission();
      if (permission !== 'granted') {
        triggerToast('Notification permission denied by user.', 'error');
        return;
      }

      const vapidPublicKey = process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY;
      if (!vapidPublicKey) {
        triggerToast('VAPID public key not found in env configuration.', 'error');
        return;
      }

      const urlBase64ToUint8Array = (base64Str) => {
        const padding = '='.repeat((4 - (base64Str.length % 4)) % 4);
        const base64 = (base64Str + padding).replace(/\-/g, '+').replace(/_/g, '/');
        const rawData = window.atob(base64);
        const outputArray = new Uint8Array(rawData.length);
        for (let i = 0; i < rawData.length; ++i) {
          outputArray[i] = rawData.charCodeAt(i);
        }
        return outputArray;
      };

      const convertedVapidKey = urlBase64ToUint8Array(vapidPublicKey);
      let sub = await registration.pushManager.getSubscription();
      if (!sub) {
        sub = await registration.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey: convertedVapidKey
        });
      }

      const res = await fetch(`${API_BASE_URL}/notifications/subscribe`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ subscription: sub })
      });
      const data = await res.json();
      if (res.ok && data.success) {
        triggerToast('Successfully registered this device for push notifications! 🎉', 'success');
      } else {
        triggerToast(data.message || 'Subscription failed on server.', 'error');
      }
    } catch (err) {
      console.error('Push subscription error:', err);
      triggerToast('Subscription failed: ' + err.message, 'error');
    }
  };

