  // Moves a category one place up (-1) or down (+1). The list updates straight away and goes back to
  // the saved order if the server doesn't accept it.
  const handleMoveCategory = async (index, direction) => {
    const target = index + direction;
    if (isCategoryOrderSaving || target < 0 || target >= categories.length) return;
    const previous = categories;
    const reordered = [...categories];
    [reordered[index], reordered[target]] = [reordered[target], reordered[index]];
    setCategories(reordered);
    setIsCategoryOrderSaving(true);
    try {
      const authToken = token || localStorage.getItem('vaugun_token');
      const res = await fetch(`${API_BASE_URL}/categories/order`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${authToken}` },
        body: JSON.stringify({ ids: reordered.map(c => c._id) })
      });
      const data = await res.json().catch(() => ({}));
      if (res.ok && data.success && Array.isArray(data.data)) {
        setCategories(data.data);
      } else {
        setCategories(previous);
        triggerToast(data.message || 'Could not save the category order', 'error');
      }
    } catch (error) {
      console.error('Category Order Error:', error);
      setCategories(previous);
      triggerToast('Server error while saving the category order', 'error');
    } finally {
      setIsCategoryOrderSaving(false);
    }
  };

