  const checkVariantMismatches = (selectedProdIds) => {
    const selectedProductsList = products.filter(p => selectedProdIds.includes(p._id || p.id));
    const variantsByName = {};
    const rootPricingProducts = [];
    
    selectedProductsList.forEach(p => {
      if (p.variants && p.variants.length > 0) {
        p.variants.forEach(v => {
          const nameKey = (v.name || '').trim().toLowerCase();
          if (!variantsByName[nameKey]) {
            variantsByName[nameKey] = [];
          }
          variantsByName[nameKey].push({ product: p, variant: v });
        });
      } else {
        rootPricingProducts.push(p);
      }
    });

    const mismatches = [];

    // 1. Variant-level check
    Object.keys(variantsByName).forEach(nameKey => {
      const items = variantsByName[nameKey];
      if (items.length > 1) {
        const baseItem = items[0];
        const baseName = baseItem.variant.name;
        const basePrice = Number(baseItem.variant.price) || 0;
        const baseBulkPrice = Number(baseItem.variant.bulkPrice) || 0;
        const baseBulkMinQty = Number(baseItem.variant.bulkMinQty) || 0;

        for (let i = 1; i < items.length; i++) {
          const currentItem = items[i];
          const curPrice = Number(currentItem.variant.price) || 0;
          const curBulkPrice = Number(currentItem.variant.bulkPrice) || 0;
          const curBulkMinQty = Number(currentItem.variant.bulkMinQty) || 0;

          if (basePrice !== curPrice || baseBulkPrice !== curBulkPrice || baseBulkMinQty !== curBulkMinQty) {
            mismatches.push({
              type: 'variant',
              name: baseName,
              details: `${baseItem.product.name} (Price: ₹${basePrice}, Bulk: ₹${baseBulkPrice}, Min: ${baseBulkMinQty}) vs ${currentItem.product.name} (Price: ₹${curPrice}, Bulk: ₹${curBulkPrice}, Min: ${curBulkMinQty})`
            });
            break;
          }
        }
      }
    });

    // 2. Root-level check
    if (rootPricingProducts.length > 1) {
      const baseItem = rootPricingProducts[0];
      const basePrice = Number(baseItem.price) || 0;
      const baseBulkPrice = Number(baseItem.bulkPrice) || 0;
      const baseBulkMinQty = Number(baseItem.bulkMinQty) || 0;

      for (let i = 1; i < rootPricingProducts.length; i++) {
        const currentItem = rootPricingProducts[i];
        const curPrice = Number(currentItem.price) || 0;
        const curBulkPrice = Number(currentItem.bulkPrice) || 0;
        const curBulkMinQty = Number(currentItem.bulkMinQty) || 0;

        if (basePrice !== curPrice || baseBulkPrice !== curBulkPrice || baseBulkMinQty !== curBulkMinQty) {
          mismatches.push({
            type: 'root',
            name: 'Root Pricing (No Variants)',
            details: `${baseItem.name} (Price: ₹${basePrice}, Bulk: ₹${baseBulkPrice}, Min: ${baseBulkMinQty}) vs ${currentItem.name} (Price: ₹${curPrice}, Bulk: ₹${curBulkPrice}, Min: ${curBulkMinQty})`
          });
          break;
        }
      }
    }

    return mismatches;
  };

