                                            const updated = [...newProdSpecs];
                                            const currentObj = typeof updated[index] === 'object' && updated[index] !== null ? updated[index] : { key: '', value: '' };
                                            updated[index] = { ...currentObj, key: e.target.value };
                                            setNewProdSpecs(updated);
