                    e.preventDefault();
                    if (!newCouponCode || !newCouponValue || !newCouponMinPurchase || !newCouponLimit) {
                      triggerToast("Please fill out all fields", "error");
                      return;
                    }
                    if (newCouponCategory === 'other' && !customCouponCategory) {
                      triggerToast("Please enter a custom category name", "error");
                      return;
                    }
                    const upperCode = newCouponCode.toUpperCase().trim();
                    if (coupons.some(c => c.code && c.code.toUpperCase().trim() === upperCode)) {
                      triggerToast("A coupon with this code already exists!", "error");
                      return;
                    }
                    const finalCategory = newCouponCategory === 'other' ? customCouponCategory.trim() : newCouponCategory;
                    const newCoupon = {
                      code: upperCode,
                      discountType: newCouponType,
                      discountValue: parseFloat(newCouponValue),
                      minPurchase: parseFloat(newCouponMinPurchase),
                      usageLimit: parseInt(newCouponLimit),
                      category: finalCategory || 'other'
                    };
                    setCoupons([...coupons, newCoupon]);
                    setNewCouponCode('');
                    setNewCouponValue('');
                    setNewCouponMinPurchase('');
                    setNewCouponLimit('');
                    setNewCouponCategory('welcome');
                    setCustomCouponCategory('');
